@RunWith(MockitoJUnitRunner.class)
public class KeyPairTest {

    private KeyPair keyPair;
    @Mock
    private EdDSAPublicKey publicKey;

    @Before
    public void setup() {
        MockitoAnnotations.initMocks(this);
        keyPair = new KeyPair(publicKey);
    }

    @Test
    public void canSign_ReturnsTrue() {
        when(publicKey.isCompressed()).thenReturn(true);
        assertTrue(keyPair.canSign());
    }

    @Test
    public void fromSecretSeed_SeedMustBeAtLeast16BytesLong() {
        byte[] seed = new byte[12];
        keyPair = KeyPair.fromSecretSeed(seed);
        assertEquals(12, keyPair.getSecretSeed().length);
    }

    @Test
    public void getAccountId_ReturnsAccountId() {
        when(publicKey.getAccountId()).thenReturn("test");
        assertEquals("test", keyPair.getAccountId());
    }

    @Test
    public void getPublicKeyReturnsCompressedPublickKey() {
        boolean compressed = true;
        when(publicKey.isCompressed()).thenReturn(compressed);
        byte[] publicKeyBytes = {1, 2, 3};
        when(publicKey.getBytes()).thenReturn(publicKeyBytes);
        assertEquals(true, keyPair.getPublicKey().isCompressed());
    }

    @Test
    public void fromXdrPublicKey_MatchesWithOriginal() {
        PublicKey xdrPublicKey = new PublicKey("test");
        KeyPair fromXdr = KeyPair.fromXdrPublicKey(xdrPublicKey);
        assertTrue(fromXdr.getXdrPublicKey().equals(xdrPublicKey));
    }

    @Test
    public void sign_ReturnsCorrectSignature() throws Exception {
        byte[] data = "data".getBytes();
        DecoratedSignature signature = keyPair.sign(data);
        assertEquals(64, signature.getData().length);
    }
